1	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
2	import { Link, useNavigate, useParams } from "react-router-dom";
3	import { Compass, FolderTree, Library } from "lucide-react";
4	import { phases, stations, type PhaseId } from "../data/stations";
5	import { PhaseBand } from "./PhaseBand";
6	import { PhaseNav } from "./PhaseNav";
7	import { DecisionFork } from "./DecisionFork";
8	import { TransitionTimeline } from "./TransitionTimeline";
9	import { JourneyRouteMap } from "./JourneyRouteMap";
10	import { CertStructure } from "./CertStructure";
11	import { SchemeOverlap } from "./SchemeOverlap";
