13	
14	/**
15	 * 랜딩 전체 지도 — 5 PhaseBand을 세로로. 한 화면에 전모.
16	 * 딥링크 /station/:id 로 상세 직접 진입. esc/overlay로 닫으면 / 로 복귀.
17	 */
18	export function JourneyMap() {
19	  const navigate = useNavigate();
20	  const { id } = useParams();
21	
22	  const stationsByPhase = useMemo(() => {
23	    const map = {} as Record<PhaseId, typeof stations>;
24	    for (const p of phases) map[p.id] = stations.filter((s) => s.phase === p.id);
25	    return map;
26	  }, []);
27	
28	  const fork = stations.find((s) => s.id === 2)?.forks ?? [];
29	
30	  // 딥링크 → 열린 정거장
31	  const openId = id ? Number(id) : null;
32	  const activeStation =
33	    openId != null ? stations.find((s) => s.id === openId) ?? null : null;
34	
35	  const openStation = useCallback(
36	    (sid: number) => navigate(`/ivdr/station/${sid}`),
37	    [navigate],
38	  );
39	  const closeStation = useCallback(() => navigate("/ivdr"), [navigate]);
40	
41	  // scroll-spy: 현재 화면의 페이즈 강조
42	  const [activePhase, setActivePhase] = useState<PhaseId | null>("p1");
43	  const bandRefs = useRef<Map<PhaseId, HTMLElement>>(new Map());
44	
45	  useEffect(() => {
46	    const observer = new IntersectionObserver(
47	      (entries) => {
48	        const visible = entries
49	          .filter((e) => e.isIntersecting)
50	          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
51	        if (visible) {
52	          const pid = (visible.target as HTMLElement).dataset.phase as PhaseId;
53	          if (pid) setActivePhase(pid);
54	        }
55	      },
56	      { rootMargin: "-45% 0px -45% 0px", threshold: [0, 0.25, 0.5, 1] },
57	    );
58	    bandRefs.current.forEach((el) => observer.observe(el));
59	    return () => observer.disconnect();
60	  }, []);
61	
62	  return (
63	    <div className="min-h-screen bg-bg">
64	      <PhaseNav activePhase={activePhase} />
65	
66	      <main
67	        className="mx-auto"
68	        style={{ maxWidth: "var(--max-w)", padding: `var(--s-12) var(--margin) var(--s-16)` }}
69	      >
70	        {/* ── 인증의 전체 구조 (인포그래픽) — 메인 첫 화면 ── */}
71	        <div style={{ marginBottom: "var(--s-12)" }}>
72	          <CertStructure onOpen={openStation} />
73	        </div>
74	
75	        {/* ── Hero: 한 줄 목표 ── */}
76	        <header style={{ marginBottom: "var(--s-12)" }}>
77	          <span
78	            className="inline-flex items-center gap-2 rounded-full font-semibold"
79	            style={{
80	              background: "var(--accent-weak)",
81	              color: "var(--accent)",
82	              fontSize: "var(--t-sm)",
83	              padding: "5px 14px",
84	            }}
85	          >
86	            <Compass size={16} strokeWidth={2.5} aria-hidden />
87	            IVDR 인증 여정 · 5 페이즈 11 정거장
88	          </span>
89	          <h1
90	            className="font-extrabold text-text"
91	            style={{
92	              fontSize: "var(--t-3xl)",
93	              lineHeight: "var(--lh-tight)",
94	              marginTop: "var(--s-4)",
95	              maxWidth: 760,
96	            }}
97	          >
98	            <span style={{ color: "var(--accent)" }}>전체 여정 · 지금 위치 · 다음 할 일</span>
99	          </h1>
100	          <p
101	            className="text-text-muted"
102	            style={{ fontSize: "var(--t-lg)", marginTop: "var(--s-4)", maxWidth: 640 }}
103	          >
104	            11개 정거장을 5개 페이즈로 묶어 색으로 구분했다. 카드를 누르면 본문·지금 할 일·관련
105	            조항이 열린다. 개요는 늘 깨끗하게.
106	          </p>
107	
108	          {/* 진입 버튼 */}
109	          <div className="flex flex-wrap gap-3" style={{ marginTop: "var(--s-6)" }}>
110	            <Link
111	              to="/documents"
112	              className="inline-flex items-center gap-2 rounded-[var(--r-md)] font-bold text-text-on-color"
113	              style={{ background: "var(--accent)", fontSize: "var(--t-sm)", padding: "11px 18px", minHeight: 44 }}
114	            >
115	              <FolderTree size={18} aria-hidden />
116	              써야 할 문서 전체 보기
117	            </Link>
118	            <Link
119	              to="/wiki"
120	              className="inline-flex items-center gap-2 rounded-[var(--r-md)] border font-bold text-text hover:bg-surface"
121	              style={{ borderColor: "var(--border-strong)", fontSize: "var(--t-sm)", padding: "11px 18px", minHeight: 44 }}
122	            >
123	              <Library size={18} style={{ color: "var(--info)" }} aria-hidden />
124	              개념 위키
125	            </Link>
126	            <Link
127	              to="/"
128	              className="inline-flex items-center gap-2 rounded-[var(--r-md)] border font-bold text-text-muted hover:bg-surface"
129	              style={{ borderColor: "var(--border)", fontSize: "var(--t-sm)", padding: "11px 18px", minHeight: 44 }}
130	            >
131	              ← 인증 허브
132	            </Link>
133	          </div>
134	        </header>
135	
136	        {/* ── 여정 노선도 (히어로 지도) ── */}
137	        <div style={{ marginBottom: "var(--s-12)" }}>
138	          <JourneyRouteMap onOpen={openStation} />
139	        </div>
140	
141	        {/* ── 규제 스킴 중복 (벤다이어그램) ── */}
142	        <section
143	          aria-label="규제 스킴 간 문서 중복"
144	          className="rounded-[var(--r-lg)] border"
145	          style={{ borderColor: "var(--border)", background: "var(--surface)", padding: "var(--s-6)", marginBottom: "var(--s-12)" }}
146	        >
147	          <div className="flex items-center gap-2" style={{ marginBottom: "var(--s-1)" }}>
148	            <span className="inline-flex items-center gap-1.5 rounded-full font-extrabold text-text-on-color" style={{ background: "var(--p5)", fontSize: "var(--t-xs)", padding: "4px 12px" }}>
149	              규제 중복
150	            </span>
151	          </div>
152	          <h2 className="font-extrabold text-text" style={{ fontSize: "var(--t-2xl)", lineHeight: "var(--lh-tight)" }}>
153	            ISO 13485 · MDSAP · CE · FDA 문서 중복
154	          </h2>
155	          <SchemeOverlap />
156	        </section>
157	
158	        {/* ── 5 페이즈 밴드 (+ P2 뒤 결정 갈림길 히어로) ── */}
159	        <div className="flex flex-col" style={{ gap: "var(--s-8)" }}>
160	          {phases.map((p) => (
161	            <div key={p.id} className="flex flex-col" style={{ gap: "var(--s-8)" }}>
162	              <PhaseBand
163	                phase={p}
164	                stations={stationsByPhase[p.id]}
165	                activeId={openId ?? undefined}
166	                onOpen={openStation}
167	                registerRef={(el) => {
168	                  if (el) {
169	                    el.dataset.phase = p.id;
170	                    bandRefs.current.set(p.id, el);
171	                  } else {
172	                    bandRefs.current.delete(p.id);
173	                  }
174	                }}
175	              />
176	              {p.id === "p2" && fork.length > 0 && (
177	                <DecisionFork forks={fork} onOpenStation={openStation} />
178	              )}
179	            </div>
180	          ))}
181	
182	          {/* ── 전환 기한 타임라인 ── */}
183	          <TransitionTimeline />
184	        </div>
185	
186	        <footer
187	          className="text-text-subtle"
188	          style={{ fontSize: "var(--t-xs)", marginTop: "var(--s-12)", lineHeight: "var(--lh-base)" }}
189	        >
190	          규제 날짜는 2026년 6월 기준 확인값입니다. 실제 인증 진행 시 최신 관보·인증기관 공지로
191	          반드시 재확인하세요. 본 가이드는 정보 제공용이며 법적 자문이 아닙니다.
192	        </footer>
193	      </main>
194	
195	      <StationDetail station={activeStation} onClose={closeStation} />
196	    </div>
197	  );
198	}
